    description_article, dimensions, type_finition,
    quantite_commandee, prix_unitaire, prix_total_ht,
    personnalisation, id_type_personnalisation, details_personnalisation, date_livraison_prevue
)
SELECT
    cmd.id_commande,
    908,
    COALESCE(a.id_article, NULL),
    'LIL1020-B20-LuAr',
    COALESCE(a.designation, ''),
    COALESCE('1020', ''),
    COALESCE('Frange', ''),
    40,
    COALESCE(a.prix_unitaire_base, 0),
    COALESCE(a.prix_unitaire_base, 0) * 40,
    FALSE,
    NULL,
    NULL,
    cmd.date_livraison_prevue
FROM commandes cmd
LEFT JOIN articles_catalogue a ON a.code_article = 'LIL1020-B20-LuAr'
WHERE cmd.numero_commande = 'Stock'
ON CONFLICT (id_commande, numero_ligne) DO UPDATE SET
    ref_commerciale = EXCLUDED.ref_commerciale,
    description_article = EXCLUDED.description_article,
    dimensions = EXCLUDED.dimensions,
    type_finition = EXCLUDED.type_finition,
    quantite_commandee = EXCLUDED.quantite_commandee,
    prix_unitaire = EXCLUDED.prix_unitaire,
    prix_total_ht = EXCLUDED.prix_total_ht,
    personnalisation = EXCLUDED.personnalisation,
    id_type_personnalisation = EXCLUDED.id_type_personnalisation,
    details_personnalisation = EXCLUDED.details_personnalisation;

